        entries.append({
            "order_id": record["order_id"],
            "return_id": record["return_id"],
            "stage": record_stage,
            "lines": lines,
            "can_receive": record_stage == "pending" and not blockers,
            "blockers": blockers,
        })
    entries.sort(key=lambda item: item["return_id"])
    return entries

